protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9: discriminator property renamed from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator" — keep the old name so they
        // remain readable and direct SQL queries (c.Discriminator) stay valid.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9: id values no longer include the discriminator prefix.
        // Existing documents have "Product|123" format — preserve that format
        // so FindAsync and point-reads continue to work.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // Removed: HasIndex() — EF Core 9 Cosmos provider now throws on HasIndex.
    // Manage indexing via the Azure Portal or Bicep indexing policy instead.
}

